#include "JavaSoundBank.h"
#include "../../AppPlatform.h"
#include "../../network/java/JavaPackSoundDecode.h"
#include <sstream>
#include <cmath>
#include <cstring>
namespace{
uint32_t le(const unsigned char*p,unsigned n){uint32_t v=0;for(unsigned i=0;i<n;++i)v|=uint32_t(p[i])<<(8*i);return v;}
std::vector<unsigned char> asset(AppPlatform*p,const std::string&name){auto b=p->readAssetFile(name);std::vector<unsigned char> v;if(b.data&&b.size>0&&b.size<=64*1024*1024)v.assign(b.data,b.data+b.size);delete[]b.data;return v;}
unsigned choose(uint64_t&state,unsigned bound){auto next=[&](){state=(state*0x5deece66dULL+11)&((1ULL<<48)-1);return unsigned(state>>17);};if((bound&(bound-1))==0)return unsigned((uint64_t(bound)*next())>>31);unsigned bits,val;do{bits=next();val=bits%bound;}while(uint64_t(bits-val)+(bound-1)>0x7fffffffULL);return val;}
void append(std::vector<unsigned char>&v,uint32_t n,unsigned width){for(unsigned i=0;i<width;++i)v.push_back(n>>(i*8));}
std::vector<unsigned char> wave(const JavaSoundBank::Sample&s){std::vector<unsigned char>v;size_t n=s.data.size();v.reserve(n+44);auto text=[&](const char*t){v.insert(v.end(),t,t+4);};text("RIFF");append(v,uint32_t(n+36),4);text("WAVE");text("fmt ");append(v,16,4);append(v,1,2);append(v,s.channels,2);append(v,s.rate,4);append(v,s.rate*s.channels*2,4);append(v,s.channels*2,2);append(v,16,2);text("data");append(v,uint32_t(n),4);v.insert(v.end(),s.data.begin(),s.data.end());return v;}
}
bool JavaSoundBank::wav(const std::vector<unsigned char>&v,size_t&offset,size_t&size,int&rate,int&channels){if(v.size()<12||memcmp(v.data(),"RIFF",4)||memcmp(v.data()+8,"WAVE",4))return false;bool format=false;offset=size=0;for(size_t p=12;p+8<=v.size();){uint32_t n=le(v.data()+p+4,4);size_t start=p+8;if(n>v.size()-start)return false;if(!memcmp(v.data()+p,"fmt ",4)){if(n<16||le(v.data()+start,2)!=1||le(v.data()+start+14,2)!=16)return false;channels=le(v.data()+start+2,2);rate=le(v.data()+start+4,4);format=(channels==1||channels==2)&&rate>=8000&&rate<=192000;}else if(!memcmp(v.data()+p,"data",4)){offset=start;size=n;}p=start+n+(n&1);}return format&&size>0&&size%(channels*2)==0;}
void JavaSoundBank::load(AppPlatform*p){loaded=true;auto bytes=asset(p,"sounds/java/files.tsv");std::istringstream fileInput(std::string(bytes.begin(),bytes.end()));std::string line;unsigned rows=0;while(rows++<10000&&std::getline(fileInput,line)){std::istringstream row(line);std::string id,file;Metadata info;if(!(row>>id>>file>>info.channels>>info.rate)||!javaSoundName(id)||!javaSoundFile(file)||(info.channels!=1&&info.channels!=2)||info.rate<8000||info.rate>192000)continue;namedFiles[id]=file;fileNames[file]=id;metadata[file]=info;}
 bytes=asset(p,"sounds/java/definitions.tsv");bool structured=!bytes.empty();if(!structured)bytes=asset(p,"sounds/java/events.tsv");std::istringstream input(std::string(bytes.begin(),bytes.end()));rows=0;while(rows++<30000&&std::getline(input,line)){std::istringstream row(line);Variant v;std::string id,kind;if(structured){if(!(row>>id>>kind>>v.resource>>v.weight>>v.volume>>v.pitch>>v.distance)||(kind!="file"&&kind!="event")||!javaSoundName(v.resource))continue;v.event=kind=="event";}else{if(!(row>>id>>v.file>>v.weight>>v.volume>>v.pitch>>v.distance)||!javaSoundFile(v.file))continue;auto name=fileNames.find(v.file);if(name!=fileNames.end())v.resource=name->second;}
 if(!javaSoundName(id)||v.weight==0||v.weight>100000||!std::isfinite(v.volume)||v.volume<=0||!std::isfinite(v.pitch)||v.pitch<=0||!std::isfinite(v.distance)||v.distance<=0)continue;events[id].push_back(v);}activeEvents=events;}
void JavaSoundBank::clear(){activeEvents=events;packSamples.clear();packFiles.clear();samples.clear();}
void JavaSoundBank::apply(AppPlatform*p,const std::vector<const JavaPackSounds*>&packs){if(!loaded)load(p);clear();for(const auto*pack:packs){if(!pack)continue;for(const auto&source:pack->samples){if(source.file.empty()){packFiles[source.name].clear();packSamples.erase(source.name);continue;}auto sample=std::unique_ptr<Sample>(new Sample);sample->data=source.pcm;sample->channels=source.channels;sample->rate=source.rate;sample->desc=SoundDesc(reinterpret_cast<char*>(sample->data.data()),int(sample->data.size()),sample->channels,2,sample->rate);sample->desc.name=source.name;packFiles[source.name]=source.file;packSamples[source.name]=std::move(sample);}for(const auto&definition:pack->definitions){auto&list=activeEvents[definition.name];if(definition.replace)list.clear();for(const auto&source:definition.variants){Variant v;v.resource=source.name;v.event=source.kind=="event";v.weight=source.weight;v.volume=source.volume;v.pitch=source.pitch;v.distance=source.attenuationDistance;list.push_back(std::move(v));}}}}
bool JavaSoundBank::available(const Variant&v)const{return !v.file.empty()||packFiles.count(v.resource)||packSamples.count(v.resource)||namedFiles.count(v.resource);}
uint32_t JavaSoundBank::weight(const std::string&id,std::set<std::string>&stack)const{if(stack.size()>=32||!stack.insert(id).second)return 0;auto e=activeEvents.find(id);uint64_t sum=0;if(e!=activeEvents.end())for(const auto&v:e->second)sum+=v.event?weight(v.resource,stack):(available(v)?v.weight:0);stack.erase(id);return sum<=0x7fffffff?uint32_t(sum):0;}
bool JavaSoundBank::resolve(const std::string&id,uint64_t&state,Variant&out,std::set<std::string>&stack)const{if(stack.size()>=32||stack.count(id))return false;std::set<std::string>weights=stack;auto total=weight(id,weights);if(!total)return false;stack.insert(id);auto e=activeEvents.find(id);auto random=choose(state,total);for(const auto&v:e->second){auto guard=stack;auto w=v.event?weight(v.resource,guard):(available(v)?v.weight:0);if(random>=w){random-=w;continue;}bool valid=true;if(v.event){valid=resolve(v.resource,state,out,stack);if(valid){out.volume*=v.volume;out.pitch*=v.pitch;}}else out=v;stack.erase(id);return valid;}stack.erase(id);return false;}
bool JavaSoundBank::select(AppPlatform*p,const std::string&id,uint64_t seed,Variant&v,SoundDesc&sound,bool loadPcm){if(!loaded)load(p);uint64_t state=(seed^0x5deece66dULL)&((1ULL<<48)-1);std::set<std::string>stack;if(!resolve(id,state,v,stack))return false;auto shadow=packFiles.find(v.resource);if(shadow!=packFiles.end()&&shadow->second.empty())return false;auto custom=packSamples.find(v.resource);if(custom!=packSamples.end()){v.file=packFiles.at(v.resource);sound=custom->second->desc;return true;}if(v.file.empty()){auto file=namedFiles.find(v.resource);if(file==namedFiles.end())return false;v.file=file->second;}if(!loadPcm){auto info=metadata.find(v.file);if(info!=metadata.end()){sound.channels=info->second.channels;sound.frameRate=info->second.rate;}else{sound.channels=1;sound.frameRate=44100;}return true;}auto found=samples.find(v.file);if(found==samples.end()){auto sample=std::unique_ptr<Sample>(new Sample);sample->data=asset(p,"sounds/java/"+v.file);size_t offset=0,size=0;if(!wav(sample->data,offset,size,sample->rate,sample->channels))return false;sample->desc=SoundDesc(reinterpret_cast<char*>(sample->data.data()+offset),int(size),sample->channels,2,sample->rate);sample->desc.name="java:"+v.file;found=samples.emplace(v.file,std::move(sample)).first;}sound=found->second->desc;return true;}
std::vector<std::pair<std::string,std::vector<unsigned char>>> JavaSoundBank::registrations()const{std::vector<std::pair<std::string,std::vector<unsigned char>>>out;for(const auto&item:packSamples)out.emplace_back("sounds/java/"+packFiles.at(item.first),wave(*item.second));return out;}
